/* =====================================================================     PATCHED: bud.jsExecuteBudgetQueries     Purpose : stop duplicated bud.TempResults rows from orphaning a header     Date    : 2026-09-14     Original: Database/rollback/jsExecuteBudgetQueries_BEFORE_2026-09-14.sql       Changes (search for "FIX 2026-09-14"):       1. detail INSERT is now SELECT DISTINCT  -> cannot violate          UQ_jsDocEnrtyDetail_Unique on duplicated source rows       2. header + detail wrapped in ONE transaction -> a failure can no          longer leave a committed header with zero detail rows       3. the HANA detail cursor is also DISTINCT, and is skipped entirely          when the local insert failed       Run this whole file as-is. It is one ALTER PROCEDURE batch.     ===================================================================== */    CREATE PROCEDURE [bud].[jsExecuteBudgetQueries]      @inputTable QueryTableType READONLY  AS  BEGIN      SET NOCOUNT ON;        DECLARE @executionId UNIQUEIDENTIFIER = NEWID();      DECLARE @query NVARCHAR(MAX);      DECLARE @templateId INT, @queryId INT;      DECLARE @docEntry INT;      DECLARE @branch VARCHAR(50);      DECLARE @objType NVARCHAR(50);      DECLARE @CURRENTMONTH VARCHAR(100);      DECLARE @totalStage INT;      DECLARE @currentStage INT;      DECLARE @newDocId INT;      DECLARE @comp INT;      DECLARE @company VARCHAR(MAX);      DECLARE @serverName NVARCHAR(100);      DECLARE @schemaName NVARCHAR(100);      DECLARE @HanaDetailInsertQuery NVARCHAR(MAX);      DECLARE @ObjTypeValue NVARCHAR(50), @CompanyValue NVARCHAR(100), @LineNumValue INT, @VisOrderValue INT;      DECLARE @newDocIdTable TABLE (id INT);   -- hoisted; cleared each use (same as original)        DECLARE query_cursor CURSOR LOCAL FAST_FORWARD FOR       -- OPT: lighter cursor          SELECT tempId, queryId, query FROM @inputTable;      OPEN query_cursor;      FETCH NEXT FROM query_cursor INTO @templateId, @queryId, @query;      WHILE @@FETCH_STATUS = 0      BEGIN          SET @query = 'INSERT INTO bud.TempResults (              Branch, DocEntry, ObjectName, ObjType, LineNum, VisOrder,              AcctCode, AcctName, CardCode, CardName, EFFECTMONTH, BUDGET,              SUB_BUDGET, STATE, DocDate, CreateDate, AMOUNT, CURRENTMONTH,              Current_month_Posted_Amount, Budget_Owner, OwnerCode, [Approver Name],              ApprovalCode, Current_month_Budget, Status, U_NAME, CreatedDate,              CreateTime, LineRemarks, Comments, ProcesStat, UpdateDate,              OcrCode, ACOMMENT, VCOMMENT, VerifiedStatus, ApprovedStatus, flag, executionId          )          SELECT              Branch, DocEntry, ObjectName, ObjType, LineNum, VisOrder,              AcctCode, AcctName, CardCode, CardName, EFFECTMONTH, BUDGET,              SUB_BUDGET, STATE, DocDate, CreateDate, AMOUNT, CURRENTMONTH,              Current_month_Posted_Amount, Budget_Owner, OwnerCode, [Approver Name],              ApprovalCode, Current_month_Budget, Status, U_NAME, CreatedDate,              CreateTime, LineRemarks, Comments, ProcesStat, UpdateDate,              OcrCode, ACOMMENT, VCOMMENT, VerifiedStatus, ApprovedStatus, flag,              ''' + CAST(@executionId AS NVARCHAR(36)) + '''          FROM (' + @query + ') AS QueryResults';          EXEC sp_executesql @query;            SELECT @comp = company FROM jsTemplate WHERE id = @templateId;          IF (@comp = 1) SET @company = 'OIL'; ELSE SET @company = 'BEVERAGE';            EXEC [bud].[jsGetHanaConfiguration] @company, @serverName OUTPUT, @schemaName OUTPUT;            -- OPT: stage info is invariant per template -> compute ONCE (was per-document)          SELECT @totalStage = COUNT(*) FROM jsStageTemplate WHERE templateId = @templateId;          SELECT @currentStage = stageId FROM jsStageTemplate WHERE templateId = @templateId AND priority = 1;            DECLARE rec_cursor CURSOR LOCAL FAST_FORWARD FOR      -- OPT: lighter cursor              SELECT DISTINCT DocEntry, Branch, ObjType, CURRENTMONTH              FROM bud.TempResults              WHERE flag = 'A' AND ProcesStat = 'Y' AND executionId = @executionId;          OPEN rec_cursor;          FETCH NEXT FROM rec_cursor INTO @docEntry, @branch, @objType, @CURRENTMONTH;          WHILE @@FETCH_STATUS = 0          BEGIN              IF NOT EXISTS (                  SELECT 1 FROM bud.jsDocEntry                  WHERE docEntry = @docEntry AND templateId = @templateId              )              BEGIN                  -- FIX 2026-09-14: header + detail now commit together, and the                  -- detail insert is DISTINCT so duplicated bud.TempResults rows can                  -- no longer violate UQ_jsDocEnrtyDetail_Unique and orphan the header.                  SET @newDocId = NULL;                  BEGIN TRY                      BEGIN TRAN;                        INSERT INTO bud.jsDocEntry (                          docEntry, status, currentStageId, templateId, totalStage, currentSatge, date                      )                      OUTPUT INSERTED.id INTO @newDocIdTable(id)                      VALUES (@docEntry, 'P', @currentStage, @templateId, @totalStage, 1, @CURRENTMONTH);                        SELECT @newDocId = id FROM @newDocIdTable;                        INSERT INTO bud.jsDocEnrtyDetail (objType, company, lineNum, visOrder, docId)                      SELECT DISTINCT ObjType, Branch, LineNum, VisOrder, @newDocId                      FROM bud.TempResults                      WHERE DocEntry = @docEntry AND Branch = @branch AND ObjType = @objType                        AND flag = 'A' AND ProcesStat = 'Y' AND executionId = @executionId;                        COMMIT TRAN;                  END TRY                  BEGIN CATCH                      IF @@TRANCOUNT > 0 ROLLBACK TRAN;                      SET @newDocId = NULL;                      INSERT INTO bud.jsSyncErrors (ErrorTime, ErrorMessage, ProcedureName, Query)                      VALUES (GETDATE(), ERROR_MESSAGE(), 'jsExecuteBudgetQueries-HeaderDetail',                              'docEntry=' + CAST(@docEntry AS VARCHAR(20))                            + ' templateId=' + CAST(@templateId AS VARCHAR(20)));                  END CATCH                    DELETE FROM @newDocIdTable;                    IF @newDocId IS NOT NULL                  BEGIN                    -- OPT: removed per-document #TempDetails; read detail rows directly                  DECLARE detail_cursor CURSOR LOCAL FAST_FORWARD FOR                      SELECT DISTINCT ObjType, Branch, LineNum, VisOrder                      FROM bud.TempResults                      WHERE DocEntry = @docEntry AND Branch = @branch AND ObjType = @objType                        AND flag = 'A' AND ProcesStat = 'Y' AND executionId = @executionId;                  OPEN detail_cursor;                  FETCH NEXT FROM detail_cursor INTO @ObjTypeValue, @CompanyValue, @LineNumValue, @VisOrderValue;                  WHILE @@FETCH_STATUS = 0                  BEGIN                      SET @HanaDetailInsertQuery = 'INSERT INTO "' + @schemaName + '"."jsDocEntryDetail" ' +                          '("objType", "company", "lineNum", "visOrder", "docId") VALUES (' +                          '''' + @ObjTypeValue + ''', ' +                          '''' + @CompanyValue + ''', ' +                          CAST(@LineNumValue AS VARCHAR) + ', ' +                          CAST(@VisOrderValue AS VARCHAR) + ', ' +                          CAST(@newDocId AS VARCHAR) + ')';                      BEGIN TRY                          EXEC (@HanaDetailInsertQuery) AT HANADB112;                      END TRY                      BEGIN CATCH                          INSERT INTO bud.jsSyncErrors (ErrorTime, ErrorMessage, ProcedureName, Query)                          VALUES (GETDATE(), ERROR_MESSAGE(), 'jsExecuteBudgetQueries-DetailInsert', @HanaDetailInsertQuery);                      END CATCH                      FETCH NEXT FROM detail_cursor INTO @ObjTypeValue, @CompanyValue, @LineNumValue, @VisOrderValue;                  END                  CLOSE detail_cursor;                  DEALLOCATE detail_cursor;                  END   -- IF @newDocId IS NOT NULL              END              FETCH NEXT FROM rec_cursor INTO @docEntry, @branch, @objType, @CURRENTMONTH;          END          CLOSE rec_cursor;          DEALLOCATE rec_cursor;            DELETE FROM bud.TempResults WHERE executionId = @executionId;            FETCH NEXT FROM query_cursor INTO @templateId, @queryId, @query;      END      CLOSE query_cursor;      DEALLOCATE query_cursor;  END;
